//! Base colour (`renderVersion` 22, `BASE_COLOUR_RENDER_VERSION`): Rawtonic's
//! own correction of the neutral RAW look's colour, a smooth table of
//! CIELAB (Δa*, Δb*) by the look's CIELAB colour, added right after the base
//! look's tone curve (shader `apply_base_colour`).
//!
//! Fitted by Rawtonic (tasks BCOL1/BCOL2, notes:
//! benchmark-results/bcol1-2026-11-28, bcol2-2026-11-28) on CC0
//! raw.pixls.us photos of 282 camera models: our own neutral renders
//! against our own Camera Raw renders of the same photos, registered pixel
//! by pixel; a trilinear grid (L* every 10, a*/b* every 8 over ±96) with a
//! Laplacian smoothness term, L* kept. No profile, look table or other file
//! of another product was read or used. On 70 photos of 70 camera models
//! the fit never saw, the median ΔE00 to Camera Raw falls from 2.61 to 2.36
//! (61 of 70 photos closer), skin from 3.88 to 3.62, greys equal.
//!
//! - Stage: the table was fitted on the base look's output, so it sits
//!   there: every edit before the tone curve (white balance, exposure,
//!   tone, mixer, saturation) moves the colour the table reads, and the
//!   table, being smooth, follows. The colour tools after it (Color
//!   ranges, Grading, B&W, LUTs) select and act on the corrected colour the
//!   photographer sees.
//! - Greys stay grey: the correction fades to 0 below chroma 2
//!   (`FADE_CHROMA`), so white balance keeps its meaning.
//! - Only the neutral RAW look of new edits: a recipe made before keeps its
//!   colour, a camera profile (DCP) or a file's own look replaces it.

/// The render version from which the neutral RAW look gets the table.
pub const BASE_COLOUR_RENDER_VERSION: u64 = 22;

/// L* nodes (0, 10, …, 100).
pub const L_NODES: usize = 11;
/// a* and b* nodes (−96, −88, …, 96).
pub const AB_NODES: usize = 25;
/// L* between nodes.
pub const L_STEP: f32 = 10.0;
/// a* and b* between nodes.
pub const AB_STEP: f32 = 8.0;
/// The a* and b* of the first node (and minus that of the last).
pub const AB_LIMIT: f32 = 96.0;
/// Entries of the table.
pub const ENTRIES: usize = L_NODES * AB_NODES * AB_NODES;
/// Below this CIELAB chroma (of the look's colour) the correction fades to
/// 0 (smoothstep), so neutral colours stay neutral.
pub const FADE_CHROMA: f32 = 2.0;

/// The table as the shader reads it: one vec4 (Δa*, Δb*, 0, 0) per entry.
pub fn gpu_table() -> Vec<[f32; 4]> {
    TABLE.iter().map(|&[a, b]| [a, b, 0.0, 0.0]).collect()
}

/// The correction of a CIELAB colour (D65) of the base look's output:
/// the (Δa*, Δb*) to add. The shader's `apply_base_colour` reads the same
/// table the same way.
pub fn delta(lab: [f32; 3]) -> [f32; 2] {
    let pos = |v: f32, offset: f32, step: f32, nodes: usize| {
        let u = ((v + offset) / step).clamp(0.0, (nodes - 1) as f32 - 1e-4);
        let i = u as usize;
        (i, u - i as f32)
    };
    let (i, fu) = pos(lab[0], 0.0, L_STEP, L_NODES);
    let (j, fv) = pos(lab[1], AB_LIMIT, AB_STEP, AB_NODES);
    let (k, fw) = pos(lab[2], AB_LIMIT, AB_STEP, AB_NODES);
    let mut out = [0.0f32; 2];
    for (di, wu) in [(0, 1.0 - fu), (1, fu)] {
        for (dj, wv) in [(0, 1.0 - fv), (1, fv)] {
            for (dk, ww) in [(0, 1.0 - fw), (1, fw)] {
                let e = TABLE[((i + di) * AB_NODES + j + dj) * AB_NODES + k + dk];
                let w = wu * wv * ww;
                out[0] += e[0] * w;
                out[1] += e[1] * w;
            }
        }
    }
    let t = ((lab[1].hypot(lab[2])) / FADE_CHROMA).clamp(0.0, 1.0);
    let fade = t * t * (3.0 - 2.0 * t);
    [out[0] * fade, out[1] * fade]
}

